from ....adapters.soap import SoapAdapter


class FmSoapAdapter(SoapAdapter):

    def __init__(self, name, web_url, username, password):
        wsdl_url = f'https://{web_url}/fmAccess/services/{name}?wsdl'
        super().__init__(wsdl_url, username, password)

    @property
    def type_factory(self):
        """
        :rtype: zeep.client.Factory
        """
        return self.client.type_factory('ns0')
